const authHeader = $json.headers?.authorization || $json.headers?.Authorization || '';
const token = authHeader.replace(/^Bearer\s+/i, '');
if (!token) throw new Error('Missing JWT token');
const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
const userId = payload.sub || payload.user_id;
const body = $json.body || {};

const displayName = String(body.display_name || '').trim();
const imapHost = String(body.imap_host || '').trim();
const imapPort = parseInt(body.imap_port) || 993;
const imapUsername = String(body.imap_username || '').trim();
const password = String(body.password || '').trim();
const sslEnabled = body.ssl_enabled !== false;
const syncInterval = parseInt(body.sync_interval) || 15;
const startDate = body.start_date || null;

if (!displayName) return [{ json: { _error: 'display_name ist erforderlich', _status: 400 } }];
if (!imapHost)    return [{ json: { _error: 'imap_host ist erforderlich', _status: 400 } }];
if (!imapUsername) return [{ json: { _error: 'imap_username ist erforderlich', _status: 400 } }];
if (!password)    return [{ json: { _error: 'password ist erforderlich', _status: 400 } }];
if (imapPort < 1 || imapPort > 65535) return [{ json: { _error: 'imap_port muss zwischen 1 und 65535 liegen', _status: 400 } }];
if (syncInterval < 1 || syncInterval > 1440) return [{ json: { _error: 'sync_interval muss zwischen 1 und 1440 liegen', _status: 400 } }];

// AES-256-CBC password encryption using Node.js built-in crypto
const crypto = require('crypto');
const KEY = crypto.createHash('sha256').update('alice-mail-enc-key-2026').digest();
const iv = crypto.randomBytes(16);
const cipher = crypto.createCipheriv('aes-256-cbc', KEY, iv);
const enc = Buffer.concat([cipher.update(password, 'utf8'), cipher.final()]);
const passwordEnc = iv.toString('hex') + ':' + enc.toString('hex');

return [{ json: { userId, displayName, imapHost, imapPort, imapUsername, passwordEnc, password, sslEnabled, syncInterval, startDate } }];

