const authHeader = $json.headers?.authorization || $json.headers?.Authorization || '';
const token = authHeader.replace(/^Bearer\s+/i, '');
if (!token) throw new Error('Missing JWT token');
const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
const userId = payload.sub || payload.user_id;
const role = payload.role || 'user';
const body = $json.body || {};
const id = String(body.id || '').trim();
if (!id) return [{ json: { _error: 'id ist erforderlich', _status: 400 } }];

const updates = {};
if (body.display_name !== undefined) updates.displayName = String(body.display_name).trim();
if (body.imap_host !== undefined) updates.imapHost = String(body.imap_host).trim();
if (body.imap_port !== undefined) updates.imapPort = parseInt(body.imap_port);
if (body.imap_username !== undefined) updates.imapUsername = String(body.imap_username).trim();
if (body.ssl_enabled !== undefined) updates.sslEnabled = body.ssl_enabled !== false;
if (body.sync_interval !== undefined) updates.syncInterval = parseInt(body.sync_interval);
if (body.start_date !== undefined) updates.startDate = body.start_date || null;

let passwordEnc = null;
let password = null;
if (body.password) {
  password = String(body.password);
  const crypto = require('crypto');
  const KEY = crypto.createHash('sha256').update('alice-mail-enc-key-2026').digest();
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-cbc', KEY, iv);
  const enc = Buffer.concat([cipher.update(password, 'utf8'), cipher.final()]);
  passwordEnc = iv.toString('hex') + ':' + enc.toString('hex');
  updates.passwordEnc = passwordEnc;
}

return [{ json: { userId, role, id, updates, password } }];

const input = $('JWT+Parse: PUT Mailbox').first().json;
const row = $input.first().json;
if (!row.id) return [{ json: { _error: 'Postfach nicht gefunden', _status: 404 } }];
if (row.owner_id !== input.userId && input.role !== 'admin') {
  return [{ json: { _error: 'Keine Berechtigung', _status: 403 } }];
}
// Build dynamic SQL SET clause
const u = input.updates;
const sets = [];
const params = [input.id];
let idx = 2;
if (u.displayName !== undefined) { sets.push(`display_name = $${idx++}`); params.push(u.displayName); }
if (u.imapHost !== undefined) { sets.push(`imap_host = $${idx++}`); params.push(u.imapHost); }
if (u.imapPort !== undefined) { sets.push(`imap_port = $${idx++}::integer`); params.push(u.imapPort); }
if (u.imapUsername !== undefined) { sets.push(`imap_username = $${idx++}`); params.push(u.imapUsername); }
if (u.sslEnabled !== undefined) { sets.push(`ssl_enabled = $${idx++}::boolean`); params.push(u.sslEnabled); }
if (u.syncInterval !== undefined) { sets.push(`sync_interval = $${idx++}::integer`); params.push(u.syncInterval); }
if (u.startDate !== undefined) { sets.push(`start_date = $${idx++}::date`); params.push(u.startDate); }
if (u.passwordEnc !== undefined) { sets.push(`password_enc = $${idx++}`); params.push(u.passwordEnc); }
if (sets.length === 0) return [{ json: { _error: 'Keine Felder zum Aktualisieren', _status: 400 } }];
const sql = `UPDATE alice.imap_mailboxes SET ${sets.join(', ')}, status = 'active', last_error = NULL WHERE id = $1::uuid RETURNING id::text, display_name, imap_host, imap_port, imap_username, ssl_enabled, sync_interval, start_date::text, status, mails_indexed, updated_at::text`;
return [{ json: { sql, params, mailboxId: input.id } }];

